<template><div class="page-stack"><PageHeader title="后台管理员" description="真实管理员账号只读列表；新增与状态变更尚未开放。"/><SearchPanel><el-form inline><el-form-item label="角色"><el-select v-model="role" clearable style="width:170px"><el-option label="ROOT_ADMIN" value="ROOT_ADMIN"/><el-option label="SUPER_ADMIN" value="SUPER_ADMIN"/><el-option label="PLATFORM_ADMIN" value="PLATFORM_ADMIN"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="status" clearable style="width:140px"><el-option label="正常" value="ACTIVE"/><el-option label="禁用" value="DISABLED"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form></SearchPanel><el-alert v-if="error" :title="error" type="error" show-icon/><DataTable><el-table v-loading="loading" :data="items" stripe><el-table-column prop="id" label="ID"/><el-table-column prop="username" label="用户名"/><el-table-column prop="displayName" label="显示名"/><el-table-column label="角色"><template #default="{row}"><RoleTag :role="row.role"/></template></el-table-column><el-table-column label="状态"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column prop="lastLoginAt" label="最后登录" min-width="180"/></el-table></DataTable></div></template>
<script setup lang="ts">
import{onMounted,ref}from'vue';import{getApiErrorMessage}from'@/api/client';import{listAdmins}from'@/api/management';import DataTable from'@/components/DataTable.vue';import PageHeader from'@/components/PageHeader.vue';import RoleTag from'@/components/RoleTag.vue';import SearchPanel from'@/components/SearchPanel.vue';import StatusTag from'@/components/StatusTag.vue';import type{AdminRole,ManagedAdmin}from'@/types/api';const role=ref<AdminRole|''>(''),status=ref(''),items=ref<ManagedAdmin[]>([]),loading=ref(false),error=ref('');async function load(){loading.value=true;error.value='';try{items.value=(await listAdmins({role:role.value,status:status.value,page:1,pageSize:100})).items}catch(e){error.value=getApiErrorMessage(e)}finally{loading.value=false}}onMounted(load);
</script>
